This module monkey-patches a curated set of blocking I/O primitives so that any
call made from within a running event loop raises :class:`BlockingError`. Calls
made when no event loop is running behave exactly as before, so synchronous code
(and work offloaded to worker threads via ``asyncio.to_thread``) is unaffected.

A few well-known contexts are explicitly allowed so that the test infrastructure
itself does not trip the detector:

* ``time.sleep`` is allowed while a PyDev debugger is suspended on a breakpoint.
* File reads are allowed from pytest's assertion-rewrite import hook and from
  importlib ``FileLoader`` machinery (module imports).
* File writes are allowed to ``sys.stdout``/``sys.stderr`` and from pytest's
  assertion-rewrite import hook.
"""

from __future__ import annotations

import asyncio
import io
import os
import socket
import ssl
import sys
import time
from typing import Callable

from forbiddenfruit import curse

__all__ = ["BlockingError", "init"]


class BlockingError(Exception):
    """Raised when a blocking I/O operation is detected inside an async context."""


# Guard so ``init()`` is idempotent -- patching twice would wrap the wrappers.
_initialized = False


def _in_async_context() -> bool:
    """Return ``True`` when a running event loop exists in the current thread."""
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return False
    return True


def _stack_contains(predicate: Callable[[object], bool]) -> bool:
    """Return ``True`` if any frame on the current stack matches ``predicate``."""
    frame = sys._getframe(1)  # noqa: SLF001
    while frame is not None:
        try:
            if predicate(frame):
                return True
        except Exception:  # noqa: BLE001 - a bad frame must never mask the real error
            pass
        frame = frame.f_back
    return False


# --- Allow predicates -------------------------------------------------------


def _is_debugger_frame(frame) -> bool:
    """Detect a PyDev debugger wait-suspend frame."""
    code = frame.f_code
    return code.co_name == "_do_wait_suspend" or (
        "pydevd" in code.co_filename and "wait_suspend" in code.co_name
    )


def _is_pytest_rewrite_frame(frame) -> bool:
    """Detect pytest's assertion-rewrite import hook."""
    filename = frame.f_code.co_filename.replace("\\", "/")
    return "_pytest/assertion/rewrite.py" in filename or (
        "assertion" in filename and filename.endswith("rewrite.py")
    )


def _is_file_loader_frame(frame) -> bool:
    """Detect importlib ``FileLoader`` machinery reading a module's bytes."""
    code = frame.f_code
    return code.co_name == "get_data" and "importlib" in code.co_filename


def _debugger_active() -> bool:
    return _stack_contains(_is_debugger_frame)


def _read_allowed(_args, _kwargs) -> bool:
    return _stack_contains(_is_pytest_rewrite_frame) or _stack_contains(_is_file_loader_frame)


def _std_streams() -> set:
    streams = set()
    for name in ("stdout", "stderr", "__stdout__", "__stderr__"):
        stream = getattr(sys, name, None)
        if stream is not None:
            streams.add(id(stream))
            buffer = getattr(stream, "buffer", None)
            if buffer is not None:
                streams.add(id(buffer))
    return streams


def _write_allowed(args, _kwargs) -> bool:
    target = args[0] if args else None
    if target is not None and id(target) in _std_streams():
        return True
    return _stack_contains(_is_pytest_rewrite_frame)


def _sleep_allowed(_args, _kwargs) -> bool:
    return _debugger_active()


# --- Patching machinery -----------------------------------------------------


def _make_wrapper(original: Callable, name: str, can_block: Callable | None = None) -> Callable:
    """Wrap ``original`` so it raises :class:`BlockingError` inside an event loop."""

    def wrapper(*args, **kwargs):
        if _in_async_context() and (can_block is None or not can_block(args, kwargs)):
            msg = f"Blocking call to {name} detected in an async context"
            raise BlockingError(msg)
        return original(*args, **kwargs)

    wrapper.__name__ = getattr(original, "__name__", name)
    wrapper._blockbuster_original = original  # noqa: SLF001
    return wrapper


def _patch_module(module, attr: str, can_block: Callable | None = None) -> None:
    original = getattr(module, attr)
    setattr(module, attr, _make_wrapper(original, f"{module.__name__}.{attr}", can_block))


def _patch_type(cls, attr: str, can_block: Callable | None = None) -> None:
    original = getattr(cls, attr)
    name = f"{cls.__module__}.{cls.__qualname__}.{attr}"
    setattr(cls, attr, _make_wrapper(original, name, can_block))


def _curse_type(cls, attr: str, can_block: Callable | None = None) -> None:
    original = getattr(cls, attr)
    name = f"{cls.__module__}.{cls.__qualname__}.{attr}"
    curse(cls, attr, _make_wrapper(original, name, can_block))


def init() -> None:
    """Initialize blocking-I/O detection by monkey-patching blocking primitives."""
    global _initialized
    if _initialized:
        return
    _initialized = True

    # Module-level blocking functions.
    _patch_module(time, "sleep", can_block=_sleep_allowed)
    _patch_module(os, "read")
    _patch_module(os, "write")

    # Socket send/receive family.
    for method in ("send", "sendall", "sendto"):
        _patch_type(socket.socket, method)
    for method in (
        "recv",
        "recv_into",
        "recvfrom",
        "recvfrom_into",
        "recvmsg",
        "recvmsg_into",
    ):
        _patch_type(socket.socket, method)

    # SSL socket send/receive family.
    for method in ("write", "send", "read", "recv"):
        _patch_type(ssl.SSLSocket, method)

    # Buffered / text file I/O -- these are built-in C types, so use curse().
    _curse_type(io.BufferedReader, "read", can_block=_read_allowed)
    _curse_type(io.BufferedWriter, "write", can_block=_write_allowed)
    _curse_type(io.BufferedRandom, "read", can_block=_read_allowed)
    _curse_type(io.BufferedRandom, "write", can_block=_write_allowed)
    _curse_type(io.TextIOWrapper, "read", can_block=_read_allowed)
    _curse_type(io.TextIOWrapper, "write", can_block=_write_allowed)
